#!/usr/bin/env python3
"""Generate a git-style unified diff between the last shim snapshot ('head')
and the current working tree, writing it to requirement_patches/<slug>.diff.

The repo's `git` is a shim which does not support `git diff`, so the patch
required by the task workflow is produced here instead.
"""
import os
import sys
import difflib
from pathlib import Path

REPO = Path('/workspace')
SNAP = REPO / '.git-shim' / 'snapshots' / 'head'
EXCLUDE_DIRS = {'.git', '.git-shim', '__pycache__', '.pytest_cache', '.ipynb_checkpoints'}
BINARY_SUFFIXES = {'.npz', '.png', '.pyc', '.gz', '.jpg', '.pdf'}


def walk(root: Path):
    files = {}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in EXCLUDE_DIRS]
        for name in filenames:
            full = Path(dirpath) / name
            rel = full.relative_to(root)
            files[str(rel)] = full
    return files


def read(path: Path):
    if path.suffix in BINARY_SUFFIXES:
        return None
    try:
        return path.read_text(encoding='utf-8').splitlines(keepends=True)
    except (UnicodeDecodeError, OSError):
        return None


def main():
    if len(sys.argv) != 2:
        print('usage: mkpatch.py <slug>', file=sys.stderr)
        return 2
    slug = sys.argv[1]
    old_files = walk(SNAP) if SNAP.exists() else {}
    new_files = walk(REPO)
    out = []
    for rel in sorted(set(old_files) | set(new_files)):
        old_path = old_files.get(rel)
        new_path = new_files.get(rel)
        old_lines = read(old_path) if old_path else []
        new_lines = read(new_path) if new_path else []
        if old_lines is None or new_lines is None:
            # binary / undecodable file: only note add/remove
            if (old_path is None) != (new_path is None):
                out.append('diff --git a/{0} b/{0}\n'.format(rel))
                out.append('Binary files {0} and {1} differ\n'.format(
                    'a/' + rel if old_path else '/dev/null',
                    'b/' + rel if new_path else '/dev/null'))
            continue
        if old_lines == new_lines:
            continue
        out.append('diff --git a/{0} b/{0}\n'.format(rel))
        if old_path is None:
            out.append('new file mode 100644\n')
        elif new_path is None:
            out.append('deleted file mode 100644\n')
        diff = difflib.unified_diff(
            old_lines, new_lines,
            fromfile=('a/' + rel) if old_path else '/dev/null',
            tofile=('b/' + rel) if new_path else '/dev/null',
            n=3)
        for line in diff:
            if not line.endswith('\n'):
                line += '\n\\ No newline at end of file\n'
            out.append(line)
    if not out:
        print('ERROR: no changes detected; refusing to write empty patch',
              file=sys.stderr)
        return 1
    dest = REPO / 'requirement_patches' / (slug + '.diff')
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(''.join(out), encoding='utf-8')
    print('wrote {0} ({1} bytes)'.format(dest, dest.stat().st_size))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

