import difflib
from pathlib import Path

REPO = Path('/workspace')
SNAP = REPO / '.git-shim' / 'snapshots' / 'head'
EXCLUDE_DIRS = {'.git', '.git-shim', '__pycache__', '.pytest_cache', '.ipynb_checkpoints'}
BINARY_SUFFIXES = {'.npz', '.png', '.pyc', '.gz', '.jpg', '.pdf'}


def walk(root: Path):
    files = {}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in EXCLUDE_DIRS]
        for name in filenames:
            full = Path(dirpath) / name
            rel = full.relative_to(root)
            files[str(rel)] = full
    return files


def read(path: Path):
    if path.suffix in BINARY_SUFFIXES:
        return None
    try:
        return path.read_text(encoding='utf-8').splitlines(keepends=True)
    except (UnicodeDecodeError, OSError):
        return None


def main():
    if len(sys.argv) != 2:
        print('usage: mkpatch.py <slug>', file=sys.stderr)
        return 2
    slug = sys.argv[1]
    old_files = walk(SNAP) if SNAP.exists() else {}
    new_files = walk(REPO)
    out = []
    for rel in sorted(set(old_files) | set(new_files)):
        old_path = old_files.get(rel)
        new_path = new_files.get(rel)
        old_lines = read(old_path) if old_path else []
        new_lines = read(new_path) if new_path else []
        if old_lines is None or new_lines is None:
            # binary / undecodable file: only note add/remove
            if (old_path is None) != (new_path is None):
                out.append('diff --git a/{0} b/{0}\n'.format(rel))
                out.append('Binary files {0} and {1} differ\n'.format(
