@staticmethod
def _select_progress_bar(notebook):
    """Selects the progress bar class to use during training runs.

    The notebook progress bar needs `ipywidgets` to be installed, so fall
    back to the plain text bar when it is not available.
    """
    if not notebook:
        return tqdm.tqdm
    try:
        import ipywidgets  # noqa: F401 - required by the notebook bar
        from tqdm import notebook as tqdm_notebook
        return tqdm_notebook.tqdm
    except ImportError:
        return tqdm.tqdm

def _progress_bar(self, total):
    """Creates a progress bar, falling back to the plain text version.

    The notebook progress bar requires `ipywidgets` to be installed so
    gracefully degrade to the standard bar if it is not available.
    """
    try:
        return self.tqdm_progress(total=total)
    except Exception:
        return tqdm.tqdm(total=total)

@staticmethod
def _fprop_accepts_evaluation(model):
    """Whether `model.fprop` accepts an `evaluation` keyword argument.

    Models wrapping a single layer have no stochastic layers to switch
    modes for and so do not take an `evaluation` flag.
    """
    try:
        parameters = inspect.signature(model.fprop).parameters
    except (TypeError, ValueError):
        return False
    if 'evaluation' in parameters:
        return True
    return any(p.kind == inspect.Parameter.VAR_KEYWORD
               for p in parameters.values())

def _fprop_eval(self, inputs):
    """Forward propagates inputs through the model in evaluation mode."""
    if self._fprop_takes_evaluation:
        return self.model.fprop(inputs, evaluation=True)
    return self.model.fprop(inputs)

def do_training_epoch(self):
    """Do a single training epoch.

    This iterates through all batches in training dataset, for each
    calculating the gradient of the estimated error given the batch with
    respect to all the model parameters and then updates the model
    parameters according to the learning rule.
    """
    with self._progress_bar(self.train_dataset.num_batches) as train_bar:
        train_bar.set_description('Epoch Progress')
        for inputs_batch, targets_batch in self.train_dataset:
            activations = self.model.fprop(inputs_batch)
            grads_wrt_outputs = self.error.grad(
                activations[-1], targets_batch)
            grads_wrt_params = self.model.grads_wrt_params(
                activations, grads_wrt_outputs)

